// Bundled birth-guide translations (generated by `npm run i18n:sync`). A field shows its
// translation only when the English on screen is exactly the English it was translated
// from (BIRTH_GUIDE_HASHES) — a topic edited in the command center stays in English (and
// the runtime translator can take over) rather than showing a translation of older text.
import type { AppLanguage } from '../../store/useLanguageStore'
import type { BirthTopic } from '../birthGuideData'
import { fnv1a } from '../i18nHash'
import { BIRTH_GUIDE_HASHES } from './hashes'
import { ptBR } from './pt-BR'
import { es } from './es'
import type { BirthGuideLocale } from './types'

export const BIRTH_GUIDE_CONTENT: Partial<Record<AppLanguage, BirthGuideLocale>> = { 'pt-BR': ptBR, es }

export function hasBundledBirthGuide(lang: AppLanguage): boolean {
  return lang !== 'en' && !!BIRTH_GUIDE_CONTENT[lang] && Object.keys(BIRTH_GUIDE_CONTENT[lang]!).length > 0
}

export function localizedBirthTopic(topic: BirthTopic, lang: AppLanguage): BirthTopic {
  const loc = BIRTH_GUIDE_CONTENT[lang]
  if (lang === 'en' || !loc) return topic
  const tr = (key: string, english: string): string =>
    loc[key] !== undefined && BIRTH_GUIDE_HASHES[key] === fnv1a(english) ? loc[key] : english
  const t = `bg_${topic.key}`
  return {
    ...topic,
    title: tr(`${t}_title`, topic.title),
    subtitle: topic.subtitle ? tr(`${t}_subtitle`, topic.subtitle) : topic.subtitle,
    disclaimer: topic.disclaimer ? tr(`${t}_disclaimer`, topic.disclaimer) : topic.disclaimer,
    sections: topic.sections.map((s, i) => {
      const sk = `${t}_s${i}`
      return {
        ...s,
        title: tr(`${sk}_title`, s.title),
        content: tr(`${sk}_content`, s.content),
        bullets: s.bullets?.map((b, j) => tr(`${sk}_b${j}`, b)),
        subsections: s.subsections?.map((sub, k) => ({
          ...sub,
          title: tr(`${sk}_sub${k}_title`, sub.title),
          content: tr(`${sk}_sub${k}_content`, sub.content),
          bullets: sub.bullets?.map((b, j) => tr(`${sk}_sub${k}_b${j}`, b)),
        })),
        callout: s.callout
          ? { ...s.callout, title: s.callout.title ? tr(`${sk}_callout_title`, s.callout.title) : s.callout.title, text: tr(`${sk}_callout_text`, s.callout.text) }
          : s.callout,
      }
    }),
  }
}
